using System;using System.Linq;using System.Threading;using EarthUnscripted.TerrainDraft;
namespace EarthUnscripted.Editor.VerificationSupport {
static class SeamChecks {
 public static object Run(){int checks=0;void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}var plan=new TerrainSeamPlanner();var key=new TerrainSeamKey(0,0,-1);float[] knots={-32,-17.25f,-22.6117706298828125f,0};Func<float,float,SeamHeight> query=(x,z)=>new SeamHeight((float)(.3*Math.Sin(z/6)),Math.Abs(z+17.25));var a=plan.Build(key,knots,query);var b=plan.Build(key,knots.Reverse().ToArray(),query);Check(a.Count==b.Count,"Canonical independent input ordering");foreach(float t in knots)Check(Enumerable.Range(0,a.Count).Any(i=>a[i].Z==t),"Mandatory source/DEM knots retained");for(int i=0;i<a.Count;i++)Check(a[i].X==b[i].X&&a[i].Y==b[i].Y&&a[i].Z==b[i].Z,"Bitidentical neighbor seam");bool reject=false;try{new TerrainSeamPlanner(2).Build(key,new float[0],query);}catch(TerrainBudgetException){reject=true;}Check(reject,"Seam knot cap must reject rather than truncate");var cancel=new CancellationTokenSource();int visits=0;reject=false;try{plan.Build(key,knots,(x,z)=>{if(++visits==3)cancel.Cancel();return query(x,z);},cancel.Token);}catch(OperationCanceledException){reject=true;}Check(reject,"Mid-seam cancellation publishes nothing");var budget=new TerrainResidentBudget(1000,2000);Check(budget.TryAdmitReplacement(0,0,600,1000),"Admit actual counted chunk");Check(!budget.TryAdmitReplacement(1,0,500,900),"Aggregate budget rejects without dropping existing chunk");Check(budget.TryAdmitReplacement(0,0,200,300),"Replacement accounts old once");Check(budget.TryAdmitReplacement(1,0,500,900),"Replacement releases capacity");Check(budget.NumericAndRendererBufferLowerBoundBytes==52*700+24*1200,"Counts derive combined buffer bounds");budget.Release(0,0);Check(budget.NumericAndRendererBufferLowerBoundBytes==52*500+24*900,"Release exact ownership");return new{status="PASS_SHARED_SEAM_AND_RESIDENT_ADMISSION_NOT_2DMESH",checks,knots=a.Count,queries=a.QueryCount,required49cells=49*100,resident81cells=81*100,scope="Original managed 1D seam primitive and aggregate counted-resource ownership. Synthetic smoothfield fixture; no claim of actual source-aware2Dconstrained triangulation or fullworld density benchmark."};}
}

